/* ============================================
   THREAD PANEL COMPONENT
   The session-history rail of a chat or agent product: brand header,
   new-thread action, standing controls, projects, grouped history,
   profile footer. Deliberately surface-less — the host paints the band
   it sits on.

   Expand/collapse is AppSidebar's choreography, restated: the panel owns
   its width (64px rail, 280px expanded — the same constants), the sweeping
   clip and the labels' opacity fades carry the whole transition, and inner
   layout stays constant so nothing snaps mid-glide. Rows keep AppSidebar's
   geometry: 40px --radius-pill pills inset by 12px margins, so a collapsed
   row is a perfect circle around its icon (12 + 8 + 24 + 8 + 12 = 64).
   ============================================ */

.ds-thread-panel {
  /* Width and padding combine on the root and the rows, so the component
     declares its own sizing model rather than leaning on a host reset —
     without it the 64px rail renders 88 wide in a bare host. */
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  /* AppSidebar's row rhythm: one gap-xs beat between every action row,
     the new-thread row included; the larger section breaks come from the
     history's and footer's own top padding. */
  gap: var(--gap-100);
  width: 64px;
  height: 100%;
  min-height: 0;
  overflow: hidden;
  /* The inline inset lives on the panel, not the rows: every row fills
     the padded column, so the fills all stop at the same 12px breathing
     room in both states — and the collapsed circle math is unchanged
     (12 + 8 + 24 + 8 + 12 = the 64px rail). */
  padding: var(--padding-400) var(--padding-300);
  transition: width var(--motion-duration-slow) var(--motion-ease-emphasized);
}

.ds-thread-panel--expanded {
  width: 280px;
}

/* Collapsed, the whole rail is an expand target (the markup only wires
   the click when a collapse handler exists, and rows keep their own
   jobs); the cursor says so. */
.ds-thread-panel:not(.ds-thread-panel--expanded) {
  cursor: pointer;
}

/* ============================================
   HEADER — brand row and the collapse toggle
   ============================================ */

/* Collapsed, --padding-200 centres the 24px mark on the rail's axis
   (12 + 8 = the rows' icon seat); expanded it deepens to the 28px optical
   seat with everything else, the padding gliding with the sweep. The
   margin sits the brand row evenly between the panel's top edge and the
   new-thread row: 6 + 12 + the panel's 4px gap below mirrors the 16px
   panel padding + 6 above. */
.ds-thread-panel__header {
  display: flex;
  align-items: center;
  flex: none;
  min-width: 0;
  padding: var(--padding-150) var(--padding-200);
  margin-bottom: var(--gap-300);
  transition: padding var(--motion-duration-slow) var(--motion-ease-emphasized);
}

.ds-thread-panel--expanded .ds-thread-panel__header {
  padding: var(--padding-150) var(--padding-400);
}

/* A logo-less header collapsed to the rail: the empty brand slot would
   otherwise push the standing toggle off the rail's axis, so it stands
   down and the toggle centres like every other mark. */
.ds-thread-panel:not(.ds-thread-panel--expanded)
  .ds-thread-panel__header--bare {
  justify-content: center;
}

.ds-thread-panel:not(.ds-thread-panel--expanded)
  .ds-thread-panel__header--bare
  .ds-thread-panel__header-inner {
  display: none;
}

/* Collapsed, the logo doubles as the expand button (role="button" comes
   from the markup); the pointer affordance is all it needs visually. */
.ds-thread-panel__header-inner {
  display: flex;
  flex: 1;
  align-items: center;
  gap: var(--gap-200);
  min-width: 0;
}

.ds-thread-panel__header-inner[role='button'] {
  cursor: pointer;
}

.ds-thread-panel__header-inner[role='button']:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
  border-radius: var(--radius-100);
}

.ds-thread-panel__logo {
  display: inline-flex;
  flex: none;
  align-items: center;
}

/* ChatHeader's title face, so a brand here sits at the same size the
   chat's own header wears it — the two surfaces meet in one product. */
.ds-thread-panel__brand {
  min-width: 0;
  flex-shrink: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-title-body-family);
  font-size: var(--font-title-body-size);
  font-weight: var(--font-title-body-weight);
  line-height: var(--font-title-body-line-height);
  color: var(--color-text-primary);
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-thread-panel--expanded .ds-thread-panel__brand {
  opacity: 1;
}

/* The toggle folds to nothing while collapsed — the logo carries the
   expand gesture — and glides back in with the width (AppSidebar's
   mechanics: both widths explicit, so the width interpolates). */
.ds-thread-panel__toggle {
  --icon-size: var(--icon-size-600);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 0;
  height: 24px;
  flex-shrink: 0;
  padding: 0;
  border: none;
  background: none;
  color: var(--color-icon-primary);
  cursor: pointer;
  overflow: hidden;
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard),
    width var(--motion-duration-slow) var(--motion-ease-emphasized);
}

.ds-thread-panel--expanded .ds-thread-panel__toggle {
  width: 24px;
  opacity: 1;
}

/* With no logo there is nothing to hand the expand gesture to, so the
   toggle stays present in both states. */
.ds-thread-panel__toggle--standalone {
  width: 24px;
  opacity: 1;
}

.ds-thread-panel__toggle:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
  border-radius: var(--radius-100);
}

/* ============================================
   ROWS — AppSidebar's shared pill shape
   40px --radius-pill rows inset by 12px margins with 8px padding: the
   icon keeps its x-position in both states, and the collapsed hover pill
   is a circle clear of the rail edges.
   ============================================ */

.ds-thread-panel__new,
.ds-thread-panel__control,
.ds-thread-panel__project,
.ds-thread-panel__thread {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--gap-200);
  width: 100%;
  height: 40px;
  min-width: 0;
  padding: var(--padding-200);
  border: none;
  border-radius: var(--radius-pill);
  background: transparent;
  cursor: pointer;
  overflow: hidden;
  text-align: left;
  text-decoration: none;
  transition: background-color var(--motion-duration-fast)
      var(--motion-ease-standard),
    padding var(--motion-duration-slow) var(--motion-ease-emphasized);
}

/* Expanded, the rows breathe: --padding-400 inline sets the 28px optical
   seat (12 + 16) that everything in the panel aligns to — the pen icon's
   box is the guide. Collapsed returns to --padding-200, which is what the
   40px circle's math needs; the padding glides with the rail's sweep. */
.ds-thread-panel--expanded .ds-thread-panel__new,
.ds-thread-panel--expanded .ds-thread-panel__control,
.ds-thread-panel--expanded .ds-thread-panel__project,
.ds-thread-panel--expanded .ds-thread-panel__thread {
  padding: var(--padding-200) var(--padding-400);
}

.ds-thread-panel__new:hover,
.ds-thread-panel__control:hover,
.ds-thread-panel__project:hover,
.ds-thread-panel__thread:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-thread-panel__new:focus-visible,
.ds-thread-panel__control:focus-visible,
.ds-thread-panel__project:focus-visible,
.ds-thread-panel__projects-add:focus-visible,
.ds-thread-panel__thread:focus-visible,
.ds-thread-panel__more:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
}

/* ============================================
   NEW THREAD — the one filled action, always in reach
   ============================================ */

/* Deliberately as quiet as the control rows: the leading position and the
   add glyph carry the affordance, not a fill. */
.ds-thread-panel__new {
  flex: none;
}

.ds-thread-panel__new-icon {
  --icon-size: var(--icon-size-600);
  color: var(--color-icon-primary);
  flex-shrink: 0;
}

.ds-thread-panel__new-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  color: var(--color-text-primary);
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-thread-panel--expanded .ds-thread-panel__new-label {
  opacity: 1;
}

.ds-thread-panel__new-kbd {
  display: inline-flex;
  flex: none;
  gap: var(--gap-050);
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-thread-panel--expanded .ds-thread-panel__new-kbd {
  opacity: 1;
}

/* ============================================
   CONTROLS — quiet standing rows
   ============================================ */

.ds-thread-panel__controls {
  display: flex;
  flex-direction: column;
  flex: none;
  gap: var(--gap-100);
}

.ds-thread-panel__control-icon {
  --icon-size: var(--icon-size-600);
  color: var(--color-icon-primary);
  flex-shrink: 0;
}

.ds-thread-panel__control-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-primary);
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-thread-panel--expanded .ds-thread-panel__control-label {
  opacity: 1;
}

/* ============================================
   PROJECTS — standing rows under their own overline header
   Rows share the controls' anatomy (icon circles while collapsed, labels
   fading with the sweep); the header carries the section's name and the
   quiet new-project button, and fades out whole while collapsed — the
   rows' icons keep the section present on the rail.
   ============================================ */

.ds-thread-panel__projects {
  display: flex;
  flex-direction: column;
  flex: none;
  gap: var(--gap-050);
}

/* The group-label's seat and rhythm, with the add button balanced on the
   trailing edge; the vertical inset shrinks to keep the 24px button from
   growing the header past the label-only group rows below. */
.ds-thread-panel__projects-header {
  display: flex;
  align-items: center;
  gap: var(--gap-200);
  min-width: 0;
  padding: var(--padding-150) var(--padding-200) var(--padding-150)
    var(--padding-400);
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard),
    visibility 0s var(--motion-duration-base);
}

.ds-thread-panel--expanded .ds-thread-panel__projects-header {
  opacity: 1;
  visibility: visible;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard),
    visibility 0s;
}

.ds-thread-panel__projects-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  font-family: var(--font-overline-family);
  font-size: var(--font-overline-size);
  font-weight: var(--font-overline-weight);
  line-height: var(--font-overline-line-height);
  letter-spacing: var(--font-overline-letter-spacing);
  text-transform: uppercase;
  color: var(--color-text-tertiary);
}

.ds-thread-panel__projects-add {
  --icon-size: var(--icon-size-500);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  flex: none;
  padding: 0;
  border: none;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--color-icon-primary);
  cursor: pointer;
  transition: background-color var(--motion-duration-fast)
    var(--motion-ease-standard);
}

.ds-thread-panel__projects-add:hover {
  background-color: var(--color-bg-container-tertiary);
}

.ds-thread-panel__project--active {
  background-color: var(--color-bg-container-tertiary);
}

.ds-thread-panel__project-icon {
  --icon-size: var(--icon-size-600);
  color: var(--color-icon-primary);
  flex-shrink: 0;
}

.ds-thread-panel__project-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-primary);
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-thread-panel--expanded .ds-thread-panel__project-label {
  opacity: 1;
}

/* A project's meta fades with the labels — collapsed, the row is only its
   icon circle. The label fades' pace, not the menu-fade's. */
.ds-thread-panel__project .ds-thread-panel__meta {
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-thread-panel--expanded .ds-thread-panel__project .ds-thread-panel__meta {
  opacity: 1;
}

/* ============================================
   HISTORY — the one scrolling region
   Threads have no icons, so unlike AppSidebar's nav the history has no
   collapsed form: it fades out and leaves the accessibility tree and tab
   order (visibility), holding the rail's middle open.
   ============================================ */

.ds-thread-panel__history {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: var(--gap-400);
  padding-top: var(--padding-150);
  /* Tucked-away scrollbar (ChatThread's manner, without its JS): thin, no
     track fill, and invisible until the pointer is over the history. No
     reserved gutter — it would hold the history's rows 10px narrower than
     the action rows above on classic-scrollbar platforms, and the row
     widths matching matters more than a rare reflow when a long history
     first overflows. */
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard),
    visibility 0s var(--motion-duration-base);
}

.ds-thread-panel--expanded .ds-thread-panel__history {
  opacity: 1;
  visibility: visible;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard),
    visibility 0s;
}

.ds-thread-panel__history:hover {
  scrollbar-color: var(--color-divider) transparent;
}

.ds-thread-panel__group {
  display: flex;
  flex-direction: column;
  gap: var(--gap-050);
}

/* Aligned with the expanded rows' 28px optical seat. The vertical padding
   is the rows' own inset restated — as if the label sat inside a row —
   so the overline keeps the pills' rhythm instead of hugging the
   new-thread row above and the first thread below. */
.ds-thread-panel__group-label {
  padding: var(--padding-200) var(--padding-400);
  overflow: hidden;
  white-space: nowrap;
  font-family: var(--font-overline-family);
  font-size: var(--font-overline-size);
  font-weight: var(--font-overline-weight);
  line-height: var(--font-overline-line-height);
  letter-spacing: var(--font-overline-letter-spacing);
  text-transform: uppercase;
  color: var(--color-text-tertiary);
}

.ds-thread-panel__list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  /* A hairline of air between fills, so stacked hover and active pills
     never read as one slab. */
  gap: 1px;
}

/* Thread rows keep the shared 40px shape — no height override, so they
   match the new-thread and control rows exactly. The <li> is the row's
   frame: relative, so the overflow trigger can sit over the trailing
   edge without living inside the row button (nested controls are
   invalid markup). */

.ds-thread-panel__row {
  position: relative;
  min-width: 0;
}

.ds-thread-panel__thread--active {
  background-color: var(--color-bg-container-tertiary);
}

/* A row with a description wraps to two lines: the title line keeps the
   shared height's rhythm, the description takes the full second line, and
   the row's gap becomes column-only so the lines sit close. */
.ds-thread-panel__thread--detailed {
  height: auto;
  min-height: 40px;
  flex-wrap: wrap;
  column-gap: var(--gap-200);
  row-gap: 0;
}

/* The unread dot: a small status disc leading the title. Sized on the gap
   scale — there is no icon token this small, and 8px matches the title's
   cap height. */
.ds-thread-panel__unread {
  flex: none;
  width: var(--gap-200);
  height: var(--gap-200);
  border-radius: var(--radius-pill);
  background-color: var(--color-status-info-icon);
}

.ds-thread-panel__title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-primary);
  /* A long title dissolves at the trailing edge instead of clipping to an
     ellipsis — the fade is where the overflow trigger lands, so revealed
     text and control never fight. Short titles end before the fade zone
     and are untouched; the full text stays in the row's tooltip.
     ds-allow(color): mask alpha keywords (black/transparent), not palette colours */
  -webkit-mask-image: linear-gradient(
    to right,
    black calc(100% - var(--gap-1000)),
    transparent
  );
  mask-image: linear-gradient(
    to right,
    black calc(100% - var(--gap-1000)),
    transparent
  );
}

/* The naming state: a shimmer bar holds the title's place while the host
   generates a name (Skeleton's sweep restated on the row's own geometry);
   the row's accessible name stays on its tooltip. */
.ds-thread-panel__title--pending {
  display: flex;
  align-items: center;
}

.ds-thread-panel__title-shimmer {
  display: block;
  /* Full width of the title's space — the row's inline padding is the
     only inset; the title mask softens its trailing end. */
  width: 100%;
  height: 0.75em;
  border-radius: var(--radius-pill);
  background-color: var(--color-bg-container-secondary);
  position: relative;
  overflow: hidden;
}

.ds-thread-panel__title-shimmer::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--color-bg-container-primary) 50%,
    transparent 100%
  );
  /* ds-allow(motion): Skeleton's shimmer — the sweep needs a symmetric
     in-out curve no --motion-ease-* token provides; the duration is
     tokenized. */
  animation: ds-thread-panel-shimmer var(--motion-duration-loop-shimmer)
    ease-in-out infinite;
}

@keyframes ds-thread-panel-shimmer {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(100%);
  }
}

/* The description line: the caption face on the full second line, fading
   at the trailing edge like the title above it. Indented past the unread
   dot's column so both lines share a left edge.
   ds-allow(color): mask alpha keywords (black/transparent), not palette colours */
.ds-thread-panel__description {
  flex-basis: 100%;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  color: var(--color-text-tertiary);
  -webkit-mask-image: linear-gradient(
    to right,
    black calc(100% - var(--gap-1000)),
    transparent
  );
  mask-image: linear-gradient(
    to right,
    black calc(100% - var(--gap-1000)),
    transparent
  );
}

.ds-thread-panel__thread--unread .ds-thread-panel__description {
  /* The dot's width plus the row's column gap. */
  margin-left: calc(var(--gap-200) + var(--gap-200));
}

/* The trailing cluster: session glyph, pin marker, and the meta caption,
   fading together when the overflow trigger needs their edge. */
.ds-thread-panel__trail {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: var(--gap-100);
  transition: opacity var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-thread-panel__thread-icon,
.ds-thread-panel__pin {
  --icon-size: var(--icon-size-500);
  flex: none;
  color: var(--color-icon-secondary);
}

.ds-thread-panel__meta {
  flex: none;
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  color: var(--color-text-tertiary);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  transition: opacity var(--motion-duration-fast) var(--motion-ease-standard);
}

/* ============================================
   THREAD MENU — the hover-revealed overflow trigger
   A 28px circular trigger over the row's faded trailing edge, opening the
   compact DropdownMenu. Hidden until the row is hovered or holds keyboard
   focus, and held while its menu is open — never standing on a resting
   row. The meta caption steps aside as the trigger arrives, since they
   share the trailing edge.
   ============================================ */

.ds-thread-panel__row .ds-thread-panel__menu {
  position: absolute;
  top: var(--padding-150);
  right: var(--padding-150);
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-thread-panel__row:hover .ds-thread-panel__menu,
.ds-thread-panel__row:focus-within .ds-thread-panel__menu,
.ds-thread-panel__row .ds-thread-panel__menu:has([aria-expanded='true']) {
  opacity: 1;
  pointer-events: auto;
}

.ds-thread-panel__row--with-menu:hover .ds-thread-panel__trail,
.ds-thread-panel__row--with-menu:focus-within .ds-thread-panel__trail,
.ds-thread-panel__row--with-menu:has([aria-expanded='true'])
  .ds-thread-panel__trail {
  opacity: 0;
}

/* While the menu is open the pointer is off in the panel, so the row holds
   its hover wash — the open menu and its row read as one thing. */
.ds-thread-panel__row:has(.ds-thread-panel__menu [aria-expanded='true'])
  .ds-thread-panel__thread {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-thread-panel__menu-trigger {
  --icon-size: var(--icon-size-500);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: none;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--color-icon-primary);
  cursor: pointer;
  transition: background-color var(--motion-duration-fast)
    var(--motion-ease-standard);
}

.ds-thread-panel__menu-trigger:hover {
  background-color: var(--color-bg-container-tertiary);
}

.ds-thread-panel__menu-trigger:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
}

/* ============================================
   RENAME — the inline title editor
   The input wears the row's exact shape and face; the teal border is the
   active-input treatment, the one sanctioned "you are editing here" mark.
   ============================================ */

.ds-thread-panel__rename {
  box-sizing: border-box;
  width: 100%;
  height: 40px;
  min-width: 0;
  padding: 0 var(--padding-400);
  border: var(--border-025) solid var(--color-action-primary-bg);
  border-radius: var(--radius-pill);
  background-color: var(--color-bg-container-primary);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-primary);
  outline: none;
}

/* ============================================
   MORE — the quiet trailing reveal
   ============================================ */

.ds-thread-panel__more {
  align-self: flex-start;
  padding: var(--padding-150) var(--padding-400);
  border: none;
  border-radius: var(--radius-pill);
  background: transparent;
  cursor: pointer;
  white-space: nowrap;
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  color: var(--color-text-tertiary);
  transition: color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-thread-panel__more:hover {
  color: var(--color-text-secondary);
}

/* ============================================
   FOOTER — host furniture and the profile row
   The slot fades out while collapsed (AppSidebar's contract); the profile
   keeps its avatar, the texts fading with the labels above.
   ============================================ */

.ds-thread-panel__footer {
  display: flex;
  flex-direction: column;
  flex: none;
  gap: var(--gap-200);
  min-width: 0;
  /* Enough air that an overflowing history's last row never crowds the
     profile — the footer is a different region, and the space says so. */
  padding-top: var(--padding-200);
}

.ds-thread-panel__footer-slot {
  min-width: 0;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-thread-panel--expanded .ds-thread-panel__footer-slot {
  opacity: 1;
  pointer-events: auto;
}

/* Same per-state seat as the header: collapsed, --padding-100 centres the
   32px avatar on the rail's axis (12 + 4); expanded joins the 28px seat. */
.ds-thread-panel__profile {
  display: flex;
  align-items: center;
  gap: var(--gap-200);
  min-width: 0;
  padding: var(--padding-100);
  transition: padding var(--motion-duration-slow) var(--motion-ease-emphasized);
}

.ds-thread-panel--expanded .ds-thread-panel__profile {
  padding: var(--padding-100) var(--padding-400);
}

.ds-thread-panel__profile-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  color: var(--color-text-primary);
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-thread-panel--expanded .ds-thread-panel__profile-name {
  opacity: 1;
}

.ds-thread-panel__profile-meta {
  flex: none;
  overflow: hidden;
  white-space: nowrap;
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  color: var(--color-text-tertiary);
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-thread-panel--expanded .ds-thread-panel__profile-meta {
  opacity: 1;
}

import React from 'react';
import { Avatar } from '../Avatar/Avatar';
import { DropdownMenu } from '../DropdownMenu/DropdownMenu';
import { Kbd } from '../Kbd/Kbd';
import './ThreadPanel.css';
import '../../fonts/material-symbols.css';

export interface ThreadPanelThreadAction {
  /** Stable identifier reported through `onThreadAction`. */
  id: string;
  /** Menu row text. */
  label: string;
  /** Leading icon on the menu row — Material Symbol name (string) or custom element (ReactNode). */
  icon?: string | React.ReactNode;
  /** Destructive styling (the error text colour) for delete-like actions. */
  destructive?: boolean;
}

export interface ThreadPanelThread {
  /** Stable identifier: `activeThreadId` matches against it and `onThreadSelect` reports it. */
  id: string;
  /** The thread's one-line title. Overflow fades out under a trailing mask rather than clipping; the full text stays readable in the row's native tooltip. */
  title: string;
  /** Optional href — the row renders as an `<a>` for real navigation instead of a `<button>`. */
  href?: string;
  /** Small trailing annotation in the caption face, e.g. a relative timestamp. */
  meta?: string;
  /** The title is still being generated: the row shows a shimmer bar in the title's place and hides its menu, keeping `title` (e.g. "New chat") as the accessible name. */
  pending?: boolean;
  /** This thread's own menu actions, overriding the panel-wide `threadActions`. */
  actions?: ThreadPanelThreadAction[];
  /** Quiet second line under the title in the caption face — a repo, an environment, a one-line summary. Overflows under the same trailing mask as the title. */
  description?: string;
  /** The thread holds unseen activity: a small status dot leads the row. The dot is decorative — put the state in `meta` or `description` when it must be read aloud. */
  unread?: boolean;
  /** Trailing icon before the meta — Material Symbol name (string) or custom element (ReactNode), e.g. `cloud` for a session that lives remotely. */
  icon?: string | React.ReactNode;
  /** Marks the thread pinned with a trailing pin glyph. A marker only: the host groups pinned threads (typically a leading group) and offers pin/unpin through the row menu. */
  pinned?: boolean;
}

export interface ThreadPanelGroup {
  /** Group heading in the overline face, e.g. a project or repo name. Omit for an unlabelled run of threads. */
  label?: string;
  /** The group's threads, in display order. */
  threads: ThreadPanelThread[];
}

export interface ThreadPanelControl {
  /** Stable identifier reported through `onControlSelect`. */
  id: string;
  /** Leading icon on the row — Material Symbol name (string) or custom element (ReactNode). */
  icon: string | React.ReactNode;
  /** Row text. */
  label: string;
  /** Optional href — the row renders as an `<a>` instead of a `<button>`. */
  href?: string;
}

export interface ThreadPanelProject {
  /** Stable identifier: `activeProjectId` matches against it and `onProjectSelect` reports it. */
  id: string;
  /** The project's name. */
  label: string;
  /** Leading icon on the row — Material Symbol name (string) or custom element (ReactNode). Defaults to `folder`. */
  icon?: string | React.ReactNode;
  /** Small trailing annotation in the caption face, e.g. how recently the project was touched. */
  meta?: string;
  /** Optional href — the row renders as an `<a>` instead of a `<button>`. */
  href?: string;
}

export interface ThreadPanelProfile {
  /** The signed-in person's display name; also seeds the Avatar's initials. */
  name: string;
  /** Quiet caption beside the name, e.g. the plan or workspace. */
  meta?: string;
  /** Replace the initials Avatar with a custom element, e.g. an `<Avatar src>`. */
  avatar?: React.ReactNode;
}

/** Props owned by ThreadPanel itself — everything else falls through to the root `<div>`. */
type ThreadPanelOwnProps = {
  /** The history, in display order. A flat list is one group with no label. */
  groups: ThreadPanelGroup[];
  /** Id of the thread on stage. Its row renders filled and carries `aria-current`. */
  activeThreadId?: string;
  /** Fires with the clicked thread's id. Rows with an `href` navigate as well. */
  onThreadSelect?: (id: string) => void;
  /** Shared menu actions for every thread row, behind a hover-revealed trailing trigger; a thread's own `actions` overrides the set. The menu renders only when `onThreadAction` is also given, and never on a `pending` row. */
  threadActions?: ThreadPanelThreadAction[];
  /** Fires with the thread's id and the chosen action's id. */
  onThreadAction?: (threadId: string, actionId: string) => void;
  /** Accessible name for a row's menu trigger; the thread's title is appended after it. */
  threadMenuLabel?: string;
  /** Id of the thread being renamed: its row swaps to an inline text field, prefilled with the title and selected. The host owns the state, like everything else. */
  renamingThreadId?: string;
  /** Fires with the thread's id and the trimmed new title when a rename commits (Enter, or focus leaving the field). An empty or unchanged value fires `onRenameCancel` instead. */
  onThreadRename?: (threadId: string, title: string) => void;
  /** Fires when a rename ends without a change: Escape, an empty value, or an unchanged title. */
  onRenameCancel?: () => void;
  /** Accessible name for the inline rename field. */
  renameLabel?: string;
  /** Brand mark slot at the top, e.g. a logo `<img>`. While collapsed it doubles as the expand button, AppSidebar's contract. */
  logo?: React.ReactNode;
  /** Brand name beside the logo. The header row renders only when `logo`, `logoText`, or `onExpandedChange` is given. */
  logoText?: string;
  /** Text for the new-thread row. The row renders when this, `onNewThread`, or `newThreadHref` is given. */
  newThreadLabel?: string;
  /** Icon for the new-thread row — Material Symbol name (string) or custom element (ReactNode). Defaults to the pen-in-a-box `edit_square`, the same glyph chat headers use for New chat. */
  newThreadIcon?: string | React.ReactNode;
  /** Keyboard hint rendered as compact Kbds at the row's trailing edge, e.g. `["Ctrl", "N"]`. Decorative — the host owns the actual binding. */
  newThreadShortcut?: string[];
  /** Fires when the new-thread row is clicked. */
  onNewThread?: () => void;
  /** Optional href — the new-thread row renders as an `<a>`. */
  newThreadHref?: string;
  /** Standing rows between the new-thread action and the history, e.g. Automations or Settings. */
  controls?: ThreadPanelControl[];
  /** Fires with the clicked control's id. Rows with an `href` navigate as well. */
  onControlSelect?: (id: string) => void;
  /** Project rows between the standing controls and the history, under their own overline header. The section renders only when non-empty; collapsed, the rows fold to icon circles like the controls. */
  projects?: ThreadPanelProject[];
  /** The projects section's overline header text. */
  projectsLabel?: string;
  /** Id of the open project. Its row renders filled and carries `aria-current`. */
  activeProjectId?: string;
  /** Fires with the clicked project's id. Rows with an `href` navigate as well. */
  onProjectSelect?: (id: string) => void;
  /** Fires when the header's trailing new-project button is pressed. The button renders only when this is given. */
  onProjectCreate?: () => void;
  /** Accessible name for the new-project button. */
  newProjectLabel?: string;
  /** Text for the quiet trailing row that reveals older threads, e.g. "Show 20 more". Renders only when given. */
  moreLabel?: string;
  /** Fires when the more row is clicked. */
  onShowMore?: () => void;
  /** Accessible name for the scrollable history region. */
  historyLabel?: string;
  /** Whether the panel is expanded (280px, labels and history showing). Collapsed it is AppSidebar's 64px icon rail: circular icon rows, the history faded out, the avatar alone in the footer. */
  expanded?: boolean;
  /** Fires with the next state when the toggle (or, collapsed, the logo) is pressed. The toggle renders only when this is given; the panel is controlled, so the host owns the state. */
  onExpandedChange?: (expanded: boolean) => void;
  /** Accessible name for the header toggle while expanded. */
  collapseLabel?: string;
  /** Accessible name for the expand affordance while collapsed. */
  expandLabel?: string;
  /** The signed-in person, rendered as the footer's Avatar row. */
  profile?: ThreadPanelProfile;
  /** Rendered in the footer above the profile row — a theme toggle, a storage meter. Fades out while collapsed, AppSidebar's contract. */
  footerSlot?: React.ReactNode;
  /** Additional CSS classes */
  className?: string;
};

export interface ThreadPanelProps
  extends ThreadPanelOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof ThreadPanelOwnProps> {}

const baseClass = 'ds-thread-panel';

/** A row that is a `<button>`, or an `<a>` when an href is supplied (Button's pattern). */
function ActionRow({
  className,
  href,
  onClick,
  ariaCurrent,
  title,
  children,
}: {
  className: string;
  href?: string;
  onClick?: () => void;
  ariaCurrent?: 'page' | 'true';
  title?: string;
  children: React.ReactNode;
}) {
  if (href) {
    return (
      <a
        className={className}
        href={href}
        onClick={onClick}
        aria-current={ariaCurrent === 'true' ? 'page' : ariaCurrent}
        title={title}
      >
        {children}
      </a>
    );
  }
  return (
    <button
      type="button"
      className={className}
      onClick={onClick}
      aria-current={ariaCurrent}
      title={title}
    >
      {children}
    </button>
  );
}

/** The inline rename field. Uncontrolled: Enter commits, Escape cancels,
    and focus leaving the field commits too — an empty or unchanged value
    cancels instead, since half a title is not a title. The keyboard paths
    hand focus back to the row once the host swaps it in; a blur commit
    leaves focus where the user sent it. Hook-free on purpose, so the
    module stays renderable from a Server Component (the field itself only
    renders when the host wires the rename callbacks, which already means
    a client host). */
function RenameField({
  baseClass,
  defaultValue,
  label,
  onSubmit,
  onCancel,
}: {
  baseClass: string;
  defaultValue: string;
  label: string;
  onSubmit: (value: string) => void;
  onCancel?: () => void;
}) {
  const commit = (el: HTMLInputElement) => {
    const value = el.value.trim();
    if (value && value !== defaultValue) onSubmit(value);
    else onCancel?.();
  };
  /* The row's button mounts only after the host clears the rename state,
     so the hand-back polls a few frames for the swap to land — one frame
     is a race against the host's re-render. */
  const refocusRow = (el: HTMLInputElement) => {
    const row = el.closest('li');
    const tryFocus = (attempt: number) => {
      const target = row?.querySelector<HTMLElement>('button, a');
      if (target) target.focus();
      else if (attempt < 3) requestAnimationFrame(() => tryFocus(attempt + 1));
    };
    requestAnimationFrame(() => tryFocus(0));
  };
  return (
    <input
      className={`${baseClass}__rename`}
      type="text"
      defaultValue={defaultValue}
      aria-label={label}
      ref={(el) => {
        /* Focus and select once on mount; the activeElement guard keeps a
           parent re-render from re-selecting mid-typing. */
        if (el && document.activeElement !== el) {
          el.focus();
          el.select();
        }
      }}
      onKeyDown={(e) => {
        if (e.key === 'Enter') {
          e.preventDefault();
          e.stopPropagation();
          refocusRow(e.currentTarget);
          commit(e.currentTarget);
        } else if (e.key === 'Escape') {
          /* Stop here so a host dialog (the chat sheet) doesn't close on
             the same keystroke. */
          e.stopPropagation();
          refocusRow(e.currentTarget);
          onCancel?.();
        }
      }}
      onBlur={(e) => commit(e.currentTarget)}
    />
  );
}

/**
 * ThreadPanel is the session-history rail of a chat or agent product: brand
 * header, a new-thread action with an optional shortcut hint, standing
 * control rows, an optional projects section with its own new-project
 * button, the grouped thread history (the one region that scrolls), and a
 * footer for the profile row and host furniture like a theme toggle.
 * Thread rows scale from a bare title to the full detail anatomy: an
 * unread dot, a quiet description line, a trailing glyph, a pin marker,
 * and the meta caption.
 *
 * Fully controlled and stateless: the host owns the active thread, the
 * navigation, the expanded state, and what selecting a row means. Every
 * section is optional, so the panel scales from a bare thread list to the
 * full anatomy. Thread rows carry the lifecycle affordances of a real chat
 * history: a `pending` thread shows a shimmer in its title's place while
 * the host generates a name, `threadActions` puts a hover-revealed overflow
 * menu (DropdownMenu, compact) on every row for rename and delete, and
 * `renamingThreadId` swaps a row to an inline rename field — all still
 * controlled from outside. Expand and collapse follow AppSidebar's
 * choreography: the panel owns its width (280px expanded, a 64px icon rail
 * collapsed), the sweeping clip and the labels' opacity fades carry the
 * transition, rows collapse to circular icon buttons, and while collapsed
 * the logo doubles as the expand button. Carries no `'use client'`
 * directive — rendered without callbacks (href navigation only) it works
 * from a React Server Component; the menu and rename affordances need
 * callbacks, so they belong to client hosts by nature.
 *
 * Forwards a ref to the root `<div>` and spreads unrecognised props onto it.
 */
export const ThreadPanel = React.forwardRef<HTMLDivElement, ThreadPanelProps>(
  (
    {
      groups,
      activeThreadId,
      onThreadSelect,
      threadActions,
      onThreadAction,
      threadMenuLabel = 'Thread options',
      renamingThreadId,
      onThreadRename,
      onRenameCancel,
      renameLabel = 'Rename thread',
      logo,
      logoText,
      newThreadLabel,
      newThreadIcon = 'edit_square',
      newThreadShortcut,
      onNewThread,
      newThreadHref,
      controls,
      onControlSelect,
      projects,
      projectsLabel = 'Projects',
      activeProjectId,
      onProjectSelect,
      onProjectCreate,
      newProjectLabel = 'New project',
      moreLabel,
      onShowMore,
      historyLabel = 'Thread history',
      expanded = true,
      onExpandedChange,
      collapseLabel = 'Collapse the panel',
      expandLabel = 'Expand the panel',
      profile,
      footerSlot,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const classes = [
      baseClass,
      expanded && `${baseClass}--expanded`,
      className,
    ]
      .filter(Boolean)
      .join(' ');
    const iconClass = 'material-symbols-rounded';

    const showHeader = Boolean(logo || logoText || onExpandedChange);
    const showNew = Boolean(newThreadLabel || onNewThread || newThreadHref);
    const showFooter = Boolean(footerSlot || profile);

    /* Collapsed, the logo is the expand affordance (AppSidebar's pattern);
       the toggle carries it only while expanded, or always when there is
       no logo to hand the job to. */
    const logoExpands = Boolean(logo && !expanded && onExpandedChange);
    const toggle = onExpandedChange && (
      <button
        type="button"
        className={[
          `${baseClass}__toggle`,
          !logo && `${baseClass}__toggle--standalone`,
        ]
          .filter(Boolean)
          .join(' ')}
        aria-label={expanded ? collapseLabel : expandLabel}
        aria-expanded={expanded}
        onClick={() => onExpandedChange(!expanded)}
      >
        <span className={iconClass} aria-hidden="true">
          {expanded ? 'left_panel_close' : 'left_panel_open'}
        </span>
      </button>
    );

    /* Collapsed, the whole rail is an expand target: a click on its dead
       space opens it, while clicks on the rows keep their own jobs. Only
       attached when it can fire, so a callback-less render stays valid in
       a Server Component. */
    const expandOnClick =
      !expanded && onExpandedChange
        ? (e: React.MouseEvent<HTMLDivElement>) => {
            rest.onClick?.(e);
            const target = e.target as HTMLElement;
            if (target.closest("button, a, [role='button']")) return;
            onExpandedChange(true);
          }
        : undefined;

    return (
      <div
        {...rest}
        ref={ref}
        className={classes}
        onClick={expandOnClick ?? rest.onClick}
      >
        {showHeader && (
          <div
            className={[
              `${baseClass}__header`,
              !logo && `${baseClass}__header--bare`,
            ]
              .filter(Boolean)
              .join(' ')}
          >
            <div
              className={`${baseClass}__header-inner`}
              onClick={logoExpands ? () => onExpandedChange?.(true) : undefined}
              role={logoExpands ? 'button' : undefined}
              tabIndex={logoExpands ? 0 : undefined}
              aria-label={logoExpands ? expandLabel : undefined}
              onKeyDown={
                logoExpands
                  ? (e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        onExpandedChange?.(true);
                      }
                    }
                  : undefined
              }
            >
              {logo && (
                <span className={`${baseClass}__logo`} aria-hidden="true">
                  {logo}
                </span>
              )}
              {logoText && (
                <span className={`${baseClass}__brand`}>{logoText}</span>
              )}
            </div>
            {toggle}
          </div>
        )}

        {showNew && (
          <ActionRow
            className={`${baseClass}__new`}
            href={newThreadHref}
            onClick={onNewThread}
          >
            <span
              className={`${baseClass}__new-icon${typeof newThreadIcon === 'string' ? ` ${iconClass}` : ''}`}
              aria-hidden="true"
            >
              {newThreadIcon}
            </span>
            <span className={`${baseClass}__new-label`}>
              {newThreadLabel ?? 'New thread'}
            </span>
            {newThreadShortcut && newThreadShortcut.length > 0 && (
              <span className={`${baseClass}__new-kbd`} aria-hidden="true">
                {newThreadShortcut.map((key) => (
                  <Kbd key={key} size="compact">
                    {key}
                  </Kbd>
                ))}
              </span>
            )}
          </ActionRow>
        )}

        {controls && controls.length > 0 && (
          <div className={`${baseClass}__controls`}>
            {controls.map((control) => (
              <ActionRow
                key={control.id}
                className={`${baseClass}__control`}
                href={control.href}
                onClick={
                  onControlSelect
                    ? () => onControlSelect(control.id)
                    : undefined
                }
              >
                <span
                  className={`${baseClass}__control-icon${typeof control.icon === 'string' ? ` ${iconClass}` : ''}`}
                  aria-hidden="true"
                >
                  {control.icon}
                </span>
                <span className={`${baseClass}__control-label`}>
                  {control.label}
                </span>
              </ActionRow>
            ))}
          </div>
        )}

        {projects && projects.length > 0 && (
          <div className={`${baseClass}__projects`}>
            <div className={`${baseClass}__projects-header`}>
              <span className={`${baseClass}__projects-label`}>
                {projectsLabel}
              </span>
              {onProjectCreate && (
                <button
                  type="button"
                  className={`${baseClass}__projects-add`}
                  aria-label={newProjectLabel}
                  onClick={onProjectCreate}
                >
                  <span className={iconClass} aria-hidden="true">
                    add
                  </span>
                </button>
              )}
            </div>
            <ul className={`${baseClass}__list`} aria-label={projectsLabel}>
              {projects.map((project) => {
                const active = project.id === activeProjectId;
                return (
                  <li key={project.id} className={`${baseClass}__row`}>
                    <ActionRow
                      className={[
                        `${baseClass}__project`,
                        active && `${baseClass}__project--active`,
                      ]
                        .filter(Boolean)
                        .join(' ')}
                      href={project.href}
                      onClick={
                        onProjectSelect
                          ? () => onProjectSelect(project.id)
                          : undefined
                      }
                      ariaCurrent={
                        active ? (project.href ? 'page' : 'true') : undefined
                      }
                      title={project.label}
                    >
                      <span
                        className={`${baseClass}__project-icon${typeof project.icon === 'string' || project.icon == null ? ` ${iconClass}` : ''}`}
                        aria-hidden="true"
                      >
                        {project.icon ?? 'folder'}
                      </span>
                      <span className={`${baseClass}__project-label`}>
                        {project.label}
                      </span>
                      {project.meta && (
                        <span className={`${baseClass}__meta`}>
                          {project.meta}
                        </span>
                      )}
                    </ActionRow>
                  </li>
                );
              })}
            </ul>
          </div>
        )}

        <nav className={`${baseClass}__history`} aria-label={historyLabel}>
          {groups.map(
            (group, index) =>
              group.threads.length > 0 && (
                <div
                  key={group.label ?? index}
                  className={`${baseClass}__group`}
                >
                  {group.label && (
                    <span className={`${baseClass}__group-label`}>
                      {group.label}
                    </span>
                  )}
                  <ul
                    className={`${baseClass}__list`}
                    aria-label={group.label}
                  >
                    {group.threads.map((thread) => {
                      const active = thread.id === activeThreadId;
                      const actions = thread.actions ?? threadActions;
                      const showMenu = Boolean(
                        actions &&
                          actions.length > 0 &&
                          onThreadAction &&
                          !thread.pending,
                      );
                      const renaming = Boolean(
                        thread.id === renamingThreadId && onThreadRename,
                      );
                      return (
                        <li
                          key={thread.id}
                          className={[
                            `${baseClass}__row`,
                            showMenu && `${baseClass}__row--with-menu`,
                          ]
                            .filter(Boolean)
                            .join(' ')}
                        >
                          {renaming ? (
                            <RenameField
                              baseClass={baseClass}
                              defaultValue={thread.title}
                              label={renameLabel}
                              onSubmit={(value) =>
                                onThreadRename?.(thread.id, value)
                              }
                              onCancel={onRenameCancel}
                            />
                          ) : (
                            <>
                              <ActionRow
                                className={[
                                  `${baseClass}__thread`,
                                  active && `${baseClass}__thread--active`,
                                  thread.description &&
                                    !thread.pending &&
                                    `${baseClass}__thread--detailed`,
                                  thread.unread &&
                                    `${baseClass}__thread--unread`,
                                ]
                                  .filter(Boolean)
                                  .join(' ')}
                                href={thread.href}
                                onClick={
                                  onThreadSelect
                                    ? () => onThreadSelect(thread.id)
                                    : undefined
                                }
                                ariaCurrent={
                                  active
                                    ? thread.href
                                      ? 'page'
                                      : 'true'
                                    : undefined
                                }
                                title={thread.title}
                              >
                                {thread.unread && !thread.pending && (
                                  <span
                                    className={`${baseClass}__unread`}
                                    aria-hidden="true"
                                  />
                                )}
                                {thread.pending ? (
                                  /* The naming state: the shimmer holds the
                                     title's place; the row's accessible name
                                     comes from its tooltip. */
                                  <span
                                    className={`${baseClass}__title ${baseClass}__title--pending`}
                                  >
                                    <span
                                      className={`${baseClass}__title-shimmer`}
                                      aria-hidden="true"
                                    />
                                  </span>
                                ) : (
                                  <span className={`${baseClass}__title`}>
                                    {thread.title}
                                  </span>
                                )}
                                {!thread.pending &&
                                  (thread.icon ||
                                    thread.pinned ||
                                    thread.meta) && (
                                    <span className={`${baseClass}__trail`}>
                                      {thread.icon && (
                                        <span
                                          className={`${baseClass}__thread-icon${typeof thread.icon === 'string' ? ` ${iconClass}` : ''}`}
                                          aria-hidden="true"
                                        >
                                          {thread.icon}
                                        </span>
                                      )}
                                      {thread.pinned && (
                                        <span
                                          className={`${baseClass}__pin ${iconClass}`}
                                          aria-hidden="true"
                                        >
                                          keep
                                        </span>
                                      )}
                                      {thread.meta && (
                                        <span className={`${baseClass}__meta`}>
                                          {thread.meta}
                                        </span>
                                      )}
                                    </span>
                                  )}
                                {thread.description && !thread.pending && (
                                  <span
                                    className={`${baseClass}__description`}
                                  >
                                    {thread.description}
                                  </span>
                                )}
                              </ActionRow>
                              {showMenu && actions && (
                                <DropdownMenu
                                  className={`${baseClass}__menu`}
                                  align="end"
                                  size="compact"
                                  items={actions.map((action) => ({
                                    label: action.label,
                                    icon: action.icon,
                                    destructive: action.destructive,
                                    onClick: () =>
                                      onThreadAction?.(thread.id, action.id),
                                  }))}
                                  trigger={
                                    <button
                                      type="button"
                                      className={`${baseClass}__menu-trigger`}
                                      aria-label={`${threadMenuLabel}: ${thread.title}`}
                                    >
                                      <span
                                        className={iconClass}
                                        aria-hidden="true"
                                      >
                                        more_horiz
                                      </span>
                                    </button>
                                  }
                                />
                              )}
                            </>
                          )}
                        </li>
                      );
                    })}
                  </ul>
                </div>
              ),
          )}
          {moreLabel && (
            <button
              type="button"
              className={`${baseClass}__more`}
              onClick={onShowMore}
            >
              {moreLabel}
            </button>
          )}
        </nav>

        {showFooter && (
          <div className={`${baseClass}__footer`}>
            {footerSlot && (
              <div className={`${baseClass}__footer-slot`}>{footerSlot}</div>
            )}
            {profile && (
              <div
                className={`${baseClass}__profile`}
                title={expanded ? undefined : profile.name}
              >
                {profile.avatar ?? <Avatar name={profile.name} size="sm" />}
                <span className={`${baseClass}__profile-name`}>
                  {profile.name}
                </span>
                {profile.meta && (
                  <span className={`${baseClass}__profile-meta`}>
                    {profile.meta}
                  </span>
                )}
              </div>
            )}
          </div>
        )}
      </div>
    );
  },
);

ThreadPanel.displayName = 'ThreadPanel';
